"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

const COLLAPSED_WIDTH = 64;
const DEFAULT_WIDTH = 232;
const MIN_WIDTH = 200;
const MAX_WIDTH = 320;
const COLLAPSE_THRESHOLD = 140;
const MOBILE_QUERY = "(max-width: 768px)";

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function MenuIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <path d="M4 7h16M4 12h16M4 17h16" />
    </svg>
  );
}

function CloseIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <path d="M18 6 6 18M6 6l12 12" />
    </svg>
  );
}

function SearchIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <circle cx="11" cy="11" r="7" />
      <line x1="21" y1="21" x2="16.65" y2="16.65" />
    </svg>
  );
}

function GearIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <circle cx="12" cy="12" r="3" />
      <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.6 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.6a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1Z" />
    </svg>
  );
}

function UserIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <circle cx="12" cy="8.2" r="3.2" />
      <path d="M5 20c1.2-3.6 4-5.4 7-5.4s5.8 1.8 7 5.4" />
    </svg>
  );
}

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <motion.svg
      animate={{ rotate: open ? 180 : 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 32 }}
      viewBox="0 0 24 24"
      width="13"
      height="13"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className="shrink-0 text-slate-400"
    >
      <path d="m6 9 6 6 6-6" />
    </motion.svg>
  );
}

function CheckIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

export interface SidebarNavItem {
  id: string;
  label: string;
  icon: (props: { className?: string }) => ReactNode;
  badge?: number;
}

export interface SidebarNavGroup {
  label: string;
  items: SidebarNavItem[];
}

type PresenceId = "online" | "away" | "dnd" | "offline";

interface PresenceOption {
  id: PresenceId;
  label: string;
  dotClass: string;
  textClass: string;
}

const PRESENCE_OPTIONS: PresenceOption[] = [
  { id: "online", label: "Online", dotClass: "bg-emerald-500", textClass: "text-emerald-600 dark:text-emerald-400" },
  { id: "away", label: "Away", dotClass: "bg-amber-500", textClass: "text-amber-600 dark:text-amber-400" },
  { id: "dnd", label: "Do not disturb", dotClass: "bg-rose-500", textClass: "text-rose-600 dark:text-rose-400" },
  { id: "offline", label: "Offline", dotClass: "bg-slate-400 dark:bg-slate-600", textClass: "text-slate-400 dark:text-slate-500" },
];

function WorkspaceSwitcher({ workspaces }: { workspaces: string[] }) {
  const [open, setOpen] = useState(false);
  const [workspace, setWorkspace] = useState(workspaces[0]);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  return (
    <div ref={rootRef} className="relative min-w-0">
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        onKeyDown={(e) => {
          if (e.key === "Escape") setOpen(false);
        }}
        className="flex w-full min-w-0 items-center gap-2 rounded-lg py-1.5 pr-1.5 text-left transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/5"
      >
        <span aria-hidden className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-gradient-to-br from-emerald-500 to-slate-900 text-[11px] font-semibold text-white dark:from-emerald-400 dark:to-slate-700">
          {workspace[0]}
        </span>
        <span className="min-w-0 flex-1 truncate text-sm font-semibold text-slate-900 dark:text-white">{workspace}</span>
        {workspaces.length > 1 && <ChevronIcon open={open} />}
      </button>

      <AnimatePresence>
        {open && workspaces.length > 1 && (
          <motion.div
            role="listbox"
            aria-label="Workspaces"
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 34 }}
            className="absolute left-0 top-full z-30 mt-1 w-48 overflow-hidden rounded-lg border border-slate-200 bg-white p-1 shadow-lg dark:border-slate-700 dark:bg-neutral-900"
          >
            {workspaces.map((name) => (
              <button
                key={name}
                type="button"
                role="option"
                aria-selected={workspace === name}
                onClick={() => {
                  setWorkspace(name);
                  setOpen(false);
                }}
                className="flex w-full items-center justify-between gap-2 rounded-md px-2.5 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-white/5"
              >
                {name}
                {workspace === name && <CheckIcon className="h-3.5 w-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function PresenceSwitcher({ collapsed, userName }: { collapsed: boolean; userName: string }) {
  const [open, setOpen] = useState(false);
  const [status, setStatus] = useState<PresenceId>("online");
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const current = PRESENCE_OPTIONS.find((option) => option.id === status)!;

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  return (
    <div ref={rootRef} className="relative">
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={collapsed ? `Status: ${current.label}` : undefined}
        onClick={() => setOpen((v) => !v)}
        onKeyDown={(e) => {
          if (e.key === "Escape") setOpen(false);
        }}
        className="flex w-full min-w-0 items-center gap-2.5 rounded-lg py-1.5 pr-1.5 text-left transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/5"
      >
        <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-emerald-500 to-slate-900 text-white dark:from-emerald-400 dark:to-slate-700">
          <UserIcon className="h-[18px] w-[18px]" />
          <motion.span
            aria-hidden
            animate={{ scale: 1 }}
            initial={false}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 28 }}
            className={`absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full ring-2 ring-white dark:ring-neutral-950 ${current.dotClass}`}
          />
        </span>
        <motion.span
          animate={{ width: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
          className="flex min-w-0 flex-1 items-center justify-between gap-2 overflow-hidden whitespace-nowrap"
        >
          <span className="min-w-0">
            <span className="block truncate text-xs font-medium text-slate-700 dark:text-slate-200">{userName}</span>
            <span className={`block truncate text-[11px] font-medium ${current.textClass}`}>{current.label}</span>
          </span>
          <ChevronIcon open={open} />
        </motion.span>
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="listbox"
            aria-label="Set status"
            initial={{ opacity: 0, y: 4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 4, scale: 0.98 }}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 34 }}
            className="absolute bottom-full left-0 z-30 mb-1 w-44 overflow-hidden rounded-lg border border-slate-200 bg-white p-1 shadow-lg dark:border-slate-700 dark:bg-neutral-900"
          >
            {PRESENCE_OPTIONS.map((option) => (
              <button
                key={option.id}
                type="button"
                role="option"
                aria-selected={status === option.id}
                onClick={() => {
                  setStatus(option.id);
                  setOpen(false);
                }}
                className="flex w-full items-center gap-2 rounded-md px-2.5 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-white/5"
              >
                <span aria-hidden className={`h-2 w-2 shrink-0 rounded-full ${option.dotClass}`} />
                <span className="min-w-0 flex-1 truncate">{option.label}</span>
                {status === option.id && <CheckIcon className="h-3.5 w-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function NavRow({
  item,
  active,
  collapsed,
  onSelect,
}: {
  item: SidebarNavItem;
  active: boolean;
  collapsed: boolean;
  onSelect: () => void;
}) {
  const [hovered, setHovered] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const Icon = item.icon;
  const accessibleLabel = collapsed ? (item.badge !== undefined ? `${item.label}, ${item.badge} unread` : item.label) : undefined;

  return (
    <div className="relative">
      <button
        type="button"
        aria-current={active ? "page" : undefined}
        aria-label={accessibleLabel}
        onClick={onSelect}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={() => setHovered(false)}
        className={`relative flex w-full items-center rounded-lg py-2 pr-2.5 text-sm transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
          active ? "text-slate-900 dark:text-white" : "text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200"
        }`}
      >
        {active && (
          <motion.span
            layoutId="sidebar-nav-active-highlight"
            className="absolute inset-0 -z-10 rounded-lg bg-emerald-50 dark:bg-emerald-500/10"
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
          />
        )}
        <span className="relative flex h-9 w-9 shrink-0 items-center justify-center">
          <Icon className="h-[18px] w-[18px]" />
          {item.badge !== undefined && collapsed && (
            <span aria-hidden className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-emerald-500" />
          )}
        </span>
        <motion.span
          animate={{ width: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
          className="relative flex flex-1 items-center justify-between gap-2 overflow-hidden whitespace-nowrap"
        >
          <span>{item.label}</span>
          {item.badge !== undefined && (
            <span className="shrink-0 rounded-full bg-emerald-100 px-1.5 py-0.5 text-[11px] font-medium text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300">
              {item.badge}
            </span>
          )}
        </motion.span>
      </button>

      <span className="pointer-events-none absolute left-full top-1/2 z-30 ml-2 -translate-y-1/2">
        <AnimatePresence>
          {collapsed && hovered && (
            <motion.span
              aria-hidden
              initial={{ opacity: 0, x: -4 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -4 }}
              transition={{ duration: 0.12 }}
              className="block whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-[11px] font-medium text-white shadow-md dark:bg-white dark:text-slate-900"
            >
              {item.label}
            </motion.span>
          )}
        </AnimatePresence>
      </span>
    </div>
  );
}

function SidebarContent({
  groups,
  workspaces,
  userName,
  collapsed,
  activeId,
  onSelect,
  onToggleCollapsed,
  onClose,
}: {
  groups: SidebarNavGroup[];
  workspaces: string[];
  userName: string;
  collapsed: boolean;
  activeId?: string;
  onSelect: (id: string) => void;
  onToggleCollapsed?: () => void;
  onClose?: () => void;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="flex h-full min-w-0 flex-col">
      <div className="flex items-center gap-1 border-b border-slate-100 py-3 pl-2.5 pr-2 dark:border-slate-800">
        <button
          type="button"
          aria-pressed={onClose ? undefined : collapsed}
          aria-label={onClose ? "Close menu" : collapsed ? "Expand sidebar" : "Collapse sidebar"}
          onClick={onClose ?? onToggleCollapsed}
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-500 transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-white/5"
        >
          {onClose ? <CloseIcon className="h-[18px] w-[18px]" /> : <MenuIcon className="h-[18px] w-[18px]" />}
        </button>
        <motion.div
          animate={{ width: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
          className="min-w-0 flex-1 overflow-hidden"
        >
          <WorkspaceSwitcher workspaces={workspaces} />
        </motion.div>
      </div>

      <motion.div
        animate={{ height: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
        className="overflow-hidden px-3"
      >
        <div className="relative pt-3">
          <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search"
            aria-label="Search"
            className="w-full rounded-lg border border-slate-200 bg-white py-1.5 pl-8 pr-2 text-xs text-slate-700 outline-none transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:bg-neutral-900 dark:text-slate-200 dark:placeholder:text-slate-500"
          />
        </div>
      </motion.div>

      <nav aria-label="Primary" className={`min-h-0 flex-1 px-2 py-3 ${collapsed ? "overflow-visible" : "overflow-y-auto"}`}>
        {groups.map((group) => (
          <div key={group.label} className="mb-4 last:mb-0">
            <motion.p
              animate={{ height: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="overflow-hidden px-2.5 text-[10px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500"
            >
              <span className="block pb-1.5">{group.label}</span>
            </motion.p>
            <div className="space-y-0.5">
              {group.items.map((item) => (
                <NavRow key={item.id} item={item} active={activeId === item.id} collapsed={collapsed} onSelect={() => onSelect(item.id)} />
              ))}
            </div>
          </div>
        ))}
      </nav>

      <div className="border-t border-slate-100 px-2 py-3 dark:border-slate-800">
        <NavRow
          item={{ id: "settings", label: "Settings", icon: GearIcon }}
          active={activeId === "settings"}
          collapsed={collapsed}
          onSelect={() => onSelect("settings")}
        />
        <div className="mt-1">
          <PresenceSwitcher collapsed={collapsed} userName={userName} />
        </div>
      </div>
    </div>
  );
}

/**
 * A left app-shell sidebar in the mold of Linear/Notion/Vercel: persistently
 * collapsible to an icon rail on desktop (drop it inside a `flex h-screen`
 * shell), resizable by dragging its right edge (drag past the collapse
 * point and it snaps into the rail), and a hamburger-triggered slide-in
 * drawer on narrow viewports. Renders nothing inline on mobile besides a
 * small fixed trigger: the drawer itself is a fixed overlay, so it works
 * regardless of where it's mounted in the tree.
 */
export function SidebarNav({
  groups,
  activeId,
  onSelect,
  workspaces = ["Workspace"],
  userName = "You",
}: {
  groups: SidebarNavGroup[];
  activeId?: string;
  onSelect?: (id: string) => void;
  workspaces?: string[];
  userName?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [isMobile, setIsMobile] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [width, setWidth] = useState(DEFAULT_WIDTH);
  const [isDragging, setIsDragging] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const asideRef = useRef<HTMLElement>(null);
  const dragRawRef = useRef(width);

  useEffect(() => {
    const mq = window.matchMedia(MOBILE_QUERY);
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    if (!isMobile) setDrawerOpen(false);
  }, [isMobile]);

  useEffect(() => {
    if (!drawerOpen) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setDrawerOpen(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [drawerOpen]);

  const handleSelect = (id: string) => onSelect?.(id);

  const handleResizePointerDown = (e: React.PointerEvent) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    const asideEl = asideRef.current;
    if (!asideEl) return;
    const left = asideEl.getBoundingClientRect().left;
    dragRawRef.current = width;
    setIsDragging(true);
    document.body.style.userSelect = "none";

    const onMove = (ev: PointerEvent) => {
      const raw = ev.clientX - left;
      dragRawRef.current = raw;
      setWidth(clamp(raw, MIN_WIDTH, MAX_WIDTH));
    };
    const onUp = () => {
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", onUp);
      document.body.style.userSelect = "";
      setIsDragging(false);
      if (dragRawRef.current < COLLAPSE_THRESHOLD) {
        setCollapsed(true);
        setWidth(DEFAULT_WIDTH);
      }
    };
    document.addEventListener("pointermove", onMove);
    document.addEventListener("pointerup", onUp);
  };

  const handleResizeKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      setWidth((w) => clamp(w - 16, MIN_WIDTH, MAX_WIDTH));
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      setWidth((w) => clamp(w + 16, MIN_WIDTH, MAX_WIDTH));
    } else if (e.key === "Home") {
      e.preventDefault();
      setCollapsed(true);
    } else if (e.key === "End") {
      e.preventDefault();
      setWidth(MAX_WIDTH);
    }
  };

  if (isMobile) {
    return (
      <>
        <button
          type="button"
          aria-label="Open menu"
          aria-expanded={drawerOpen}
          aria-controls="sidebar-nav-drawer"
          onClick={() => setDrawerOpen(true)}
          className="fixed left-3 top-3 z-40 flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-600 shadow-sm transition-colors hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:bg-neutral-950 dark:text-slate-300 dark:hover:bg-neutral-900"
        >
          <MenuIcon className="h-[18px] w-[18px]" />
        </button>
        <AnimatePresence>
          {drawerOpen && (
            <>
              <motion.div
                key="backdrop"
                aria-hidden
                onClick={() => setDrawerOpen(false)}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: shouldReduceMotion ? 0.1 : 0.2 }}
                className="fixed inset-0 z-40 bg-slate-950/40 backdrop-blur-sm"
              />
              <motion.aside
                id="sidebar-nav-drawer"
                key="drawer"
                initial={shouldReduceMotion ? { opacity: 0 } : { x: "-100%" }}
                animate={shouldReduceMotion ? { opacity: 1 } : { x: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { x: "-100%" }}
                transition={{ type: "spring", stiffness: 380, damping: 36 }}
                style={{ width: DEFAULT_WIDTH }}
                className="fixed inset-y-0 left-0 z-50 border-r border-slate-200 bg-white shadow-2xl dark:border-slate-800 dark:bg-neutral-950"
              >
                <SidebarContent
                  groups={groups}
                  workspaces={workspaces}
                  userName={userName}
                  collapsed={false}
                  activeId={activeId}
                  onSelect={(id) => {
                    handleSelect(id);
                    setDrawerOpen(false);
                  }}
                  onClose={() => setDrawerOpen(false)}
                />
              </motion.aside>
            </>
          )}
        </AnimatePresence>
      </>
    );
  }

  return (
    <motion.aside
      ref={asideRef}
      animate={{ width: collapsed ? COLLAPSED_WIDTH : width }}
      transition={isDragging || shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 360, damping: 34 }}
      className="relative h-full shrink-0 border-r border-slate-100 bg-slate-50/60 dark:border-slate-800 dark:bg-neutral-900/40"
    >
      <SidebarContent
        groups={groups}
        workspaces={workspaces}
        userName={userName}
        collapsed={collapsed}
        activeId={activeId}
        onSelect={handleSelect}
        onToggleCollapsed={() => setCollapsed((v) => !v)}
      />

      {!collapsed && (
        <div
          role="separator"
          aria-orientation="vertical"
          aria-label="Resize sidebar"
          aria-valuenow={Math.round(width)}
          aria-valuemin={MIN_WIDTH}
          aria-valuemax={MAX_WIDTH}
          tabIndex={0}
          onPointerDown={handleResizePointerDown}
          onKeyDown={handleResizeKeyDown}
          className="group absolute right-0 top-0 z-20 h-full w-2 translate-x-1/2 cursor-col-resize touch-none focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-emerald-600"
        >
          <span
            aria-hidden
            className={`mx-auto block h-full w-px transition-colors ${
              isDragging ? "bg-emerald-500" : "bg-transparent group-hover:bg-emerald-400/70"
            }`}
          />
        </div>
      )}
    </motion.aside>
  );
}
